INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Rosti potato pancakes', 'Breakfast', 
'1 Egg\n4 Potatoes\n1 Onion\nSalt & Pepper\n2-4 tablespoons of flour', 
'1. Canola-Oil in pan to prevent sticking.\n2. Peal and grate potatoes; squeeze potatoes to remove juice.\n3. Grate Onion; Mix egg and grated Onion and grated Potatoes (no juice)\n4. Add flour until clumpy and sticks together.\n5. Put mixture in pan, flatten, cook until brown.', 
'Recipes Printout.docx');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Baked Meat lasagne (Sharyn)', 'Dinner', 
'Serves – 6\ninstant lasagne noodles\nfresh herbs in the meat sauce and lots of them\nI just make a white sauce not a béchamel and I add a fair sprinkling of parmesan to it\nUse lots of very thin layers\n250g [1/2 lb] lasagne noodles\n250g [1/2 lb] minced steak\n2 rashes bacon, chopped\n1 onion, chopped finely\n1 tablespoon chopped parsley\n1 bay leaf\nSalt and pepper to taste\n2 large tomatoes, peeled and chopped\n¼ cup beef stock\n¼ cup water\n2 tablespoons tomato paste\n½ teaspoon dried oregano\n½ teaspoon dried basil\n\nBECHAMEL SAUCE\n¼ cup grated parmesan cheese\n2½ cups of milk\n1 bay leaf\nsmall piece of onion\n2 pepper corns\n60 g [2ozs] butter\n4 tablespoons flour\npinch of nutmeg\nsalt and pepper to taste', 
'Cook the lasagne in plenty of boiling salted water, stirring occasionally for about 15 minutes. Drain and arrange on a tea towel to drain.\nPut meat, bacon, onion, parsley, bay leaf, salt and pepper into a saucepan and let brown slowly, stirring frequently.\nPour fat off pan. Add tomatoes, stock, water, and tomato paste, and stir well and then simmer for 10 to 12 minutes.\nRemove bay leaf and stir in oregano and basil.\nSpoon a layer of this sauce over the base of a lightly oiled shallow oblong baking dish, and top with some of the béchamel sauce.\nCover with a layer of noodles. Repeat these layers, ending with the meat sauce and the béchamel over that.\nSprinkle with the parmesan cheese and bake in a moderate oven for about 30 minutes, or until bubbling hot.\n\nBECHAMEL SAUCE METHOD:\nPut milk, 1 bay leaf, small piece of onion, and 2 pepper corns into a saucepan. Heat gently until small bubbles form around the edge of the milk. Remove from heat and leave 5 minutes. Then strain.\nMelt 60 g [2ozs] butter and add 4 tablespoons flour and cook stirring for 3 minutes. Add the milk mixture and cook, stirring until boiling.\nStir in a pinch of nutmeg, and salt and pepper to taste.', 
'Recipes Printout.docx');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Basic Meat Loaf (Sharyn)', 'Dinner', 
'Cooking time – 1 hour\nServes: 8\n2 lb mince\n2 teaspoons salt\n¼ teaspoon freshly ground pepper\n½ teaspoon Mixed herbs\nThymes\nA little Worchestershire Sauce\n1 cup soft breadcrumbs\n1 cup evaporated milk\n½ onion, chopped\n3 to 4 rashes of bacon', 
'Thoroughly combine all ingredients except bacon.\nPack tightly in a greased 9 X 5 inch loaf tin.\nTop with the bacon rashes.\nBake in a moderate oven (350ºF) for 1 hour or until the loaf shrinks slightly from the sides of the pan.\n\nVariations:\nPut a little tomato sauce on the bottom of the pan before putting in the meat ingredients.\nAlso instead of bacon, added a little tomato sauce on the top near the end of cooking. This gives it a glazed look.', 
'Recipes Printout.docx');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Chicken nuggets (Joe)', 'Dinner', 
'Chicken breasts\nFlour\nSalt and Pepper\nPlastic bags x2\nEggs\nBread-crumbs\nHerbs', 
'1.Cut chicken into thin pieces\n2.Chicken into first plastic bag with flour, salt and pepper to coat chicken.\n3.Whisk egg, dip floured chicken into eggs (large bowl to prevent spills).\n4.Place chicken into second plastic bag, with herbs and bread-crumbs\n5.Place battered chicken onto non-stick tray and place in oven.\n6.Cook for X mins and Y degrees.', 
'Recipes Printout.docx');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Chilli Con Carne (James)', 'Dinner', 
'Brown Rice (Rice cooker = 3 cups of rice, 6 cups of water)\nChilli con carne packet\nMinced Meat (500g)\nTomato paste (puree)\nBeef stock (1 beef cube or liquid 250ml)\nBlack Beans (Canned) (or red kidney beans) 1 can (~400g)\nBeans (Canned) (lentils/chick-peas, etc) 1 can (~400g)\nCarrot 2\nCapsicum 1\nGarlic, 4 cloves\nOnion or spring onion 1\nMushrooms handful\nTomatoes chopped (1 can)\nHerbs: Cumin, Oregano, Paprika, Cayenne pepper, Parsley (1 tbsp each)', 
'Cook rice in rice cooker (2 cups of water per 1 cup of rice).\n1.Cook Garlic and Onion for 3 minutes in big pot, then\n2.Add beef mince and cook until brown in big pot.\n3.Add all ingredients chopped or grated (Wash canned beans and add them into pot without the can''s liquid)\n4.Cook until mixture thickens (1 to 2 hours?)\n5.Check that the vegetables are cooked throughout (not raw).', 
'Recipes Printout.docx');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Chilli Mussels or Crabs (Sharyn)', 'Dinner', 
'1 red and 1 green capsicum\n½ cup spring onions or 2 whole chopped onions\n3 cloves garlic\n1 piece root ginger or 2 teaspoons ginger powder\n¼ cup Thai chilli sauce\n½ cup lemon juice\n½ cup soya sauce\n1 tablespoon sugar\n¼ cup chicken stock\n½ cup of wine of choice\n3 tablespoons of honey\n½ cup tomato sauce', 
'Sauté onions, garlic, capsicum, and ginger. Then add other ingredients and your mussel or crab catch. Crack crab shells. Simmer for 5 to 10 minutes. Serve with napkins and crusty bread.', 
'Recipes Printout.docx');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Roast Beef (James)', 'Dinner', 
'Coles Beef Oyster Blade With Pepper ~1kg', 
'Oven at 180 Degrees for 1.5 hours', 
'Recipes Printout.docx');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Fish with Lime Sauce (Sharyn)', 'Dinner', 
'4 white fish fillets\n2 tablespoons finely grated fresh parmesan cheese\n\nLime Sauce:\n2 tablespoons cornflour\n1 1/3 cup chicken stock\n½ cup lime juice\n1/3 cup brown sugar\n20g butter\n1 tablespoon chopped capers\n1 tablespoon chopped chives', 
'Blend cornflour with stock in pan. Add remaining stock in pan. Then add remaining juice, sugar butter and capers. Stir over heat until sauce boils and thickens. Stir in chives.\nPlace a sheet of foil on an oven tray. Arrange fish in a single layer over the foil. Spoon a little of the sauce over the fish. Sprinkle with parmesan cheese.\nCook fish under a hot grill until cooked thru.\nServe fish with remaining lime sauce.', 
'Recipes Printout.docx');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Meat Pie (Sharyn)', 'Dinner', 
'1 onion\n250g mince- [approximately]\n1 carrot, finely grated\n2 cups of water [ approximately]\n2 beef stock cubes[optional-as Gravox is quite salty and has flavour]\n2 tablespoon fresh parsley- or 1 tablespoon of dried parsley\nSwig of wine or dry sherry\n2 tablespoons of Gravox [ this thickens the “sauce”]\nReadymade pastry sheets-[ I buy butter puff pastry]', 
'Set oven at 200ºC and bake the bottom of the pie [pie base] for about 10 minutes until a little brown. If the base has risen and is not sitting flat in the pan, gently push it down with the back of a spoon.\nPut the mince, finely grated carrot and parsley in a heavy fry pan and immediately add one glass of water. Mix well over medium heat.\nAdd swig of wine or sherry.\nStir often over heat and add more water if necessary. Cook until the meat is browned all over.\nAdd Gravox. Stir immediately so that it does not become clumpy.\nStir on heat until thickened.\nPut meat into cooked pie base. Put pastry over the top. Fold over the edges roughly. Make several cut marks in the top pastry with a sharp knife [this lets the steam out while the pie cooks and stops it from rising too much]. Cook until browned. Serve.', 
'Recipes Printout.docx');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Pepper Steak (Sharyn)', 'Dinner', 
'4 fillet steaks\nFew pepper corns\nSalt\n2 oz butter [ ¼ cup]\n¼ pint thick cream\n1-2 tablespoon of brandy\nChopped chives or parsley', 
'Crush pepper corns with a rolling pin and press onto either side of the steak. Add a light dusting of salt.\nHeat butter in the pan and fry steak rapidly on either side for 2-3 minutes to seal in the juices.\nThen lower the heat and cook.\nWhen steaks are just cooked, lift them out of the pan onto a hot dish.\nAdd approximately ¼ pint of thick cream to fry pan and stir well. Simmer lightly. Do not boil. Add brandy. Add extra seasoning if necessary.', 
'Recipes Printout.docx');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Sausages with Onion Gravy (Sharyn)', 'Dinner', 
'Serves 4 to 6\n1 kg sausages\n1 tablespoon oil\n2 large onions\n3 tablespoon plain flour\n2 ½ cups water\n2 beef stock cubes\n2 tablespoon tomato sauce\n½ teaspoon Worcestershire Sauce\nSalt and pepper', 
'Heat oil in frying pan, add sausages and cook till golden brown and remove.\nAdd peeled and chopped onions to pan and cook until golden brown. Add flour, stir until brown, then remove from heat. Add water and stir. Then return pan to heat and stir until sauce boils and thickens.\nAdd crumbled stock cubes, tomato sauce, Worcestershire sauce and stir after each addition.\nReduce heat and add sausages, cover and simmer gently for 30 minutes.', 
'Recipes Printout.docx');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Spaghetti Bolognese (James)', 'Dinner', 
'Packet of noodles/pasta\nPaul Newman''s Tomato Sauce\nTomato Paste 50g\nHandful of Mushrooms\nMince Meat 500g\nCarrot 2\nCapsicum 1 or 2\nOnion or spring onion 1\nDiced tomatoes (1 tin)\nLeak\nGarlic 4 cloves\nRed wine\nHerbs (thyme, rosemary, oregano)\nGarlic Bread', 
'Noodles in pot of boiling water (until soft, use fork to sample pasta)\n1.Cook Garlic and Onion for 3 minutes in big pot, then\n2.Add mince to a separate pot and cook until browned,\n3.then add all other ingredients (chopped or grated) to pot.\n4.Cook until mixture thickens\n5.Check that the vegetables are cooked throughout (not raw).', 
'Recipes Printout.docx');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Sweet and Sour chicken (Zena)', 'Dinner', 
'1 small can pineapple pieces\n6 oz quartered mushrooms [Zena used tinned champignons]\n2½ ozs dry white wine [ ¼ cup]\n4 chicken joints\n1 tablespoon oil\n1 oz butter [25gm]\n¼ pint sour cream [if sour cream is unavailable, Zena used ordinary cream] [125gm]\n½ pint chicken stock [1 cup]\n1 tablespoon cornflour\n1oz roasted almonds\nSalt and pepper\n2 tablespoons drained pineapple juice', 
'Drain pineapple pieces but retain 2 tablespoons of juice.\nPlace the pineapple pieces in a saucepan with the mushrooms and white wine. Simmer gently for 5 to 7 minutes.\nRoast almonds until brown in oil and butter.\nSauté chicken joints in oil and butter until they are light golden brown. Transfer to a 3 pint casserole.\nRemove mushrooms and pineapple from the heat and carefully blend a little of the liquor with the sour cream.\nReturn this mixture to the pan and heat gently, but do not boil.\nPour the mushrooms and pineapples over the chicken pieces.\nBlend the stock, cornflour and 2 tablespoons of pineapple juice together, and add to the fat remaining in the pan.\nBring to the boil and boil 1 minute.\nAdd roasted almonds and seasoning and pour over the chicken joints.\nCook in a cool oven for 1½ hours.', 
'Recipes Printout.docx');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Yum Yum Pumpkin (Sharyn)', 'Dinner', 
'1 small whole Japanese pumpkin [about 750g]\n1 heaped cup soft white or wholemeal breadcrumbs\n1 teaspoon fresh rosemary, chopped\n1 tablespoon fresh parsley, chopped\n2 sage leaves, chopped\nScant ½ level teaspoon salt\nFew grinds black pepper\n1 level tablespoon each raisins and choice dried apricots, chopped\n2 tablespoon shelled pistachios\n2 to 3 tablespoons cream', 
'Scrub the skin of the pumpkin under cold running water. Cut a slice from the stem end and remove all the seeds. With a fine skewer pierce the pumpkin skin evenly all over. Put pumpkin into a dish [open end uppermost] add 1 tablespoon of water to the dish. Cover all over with plastic wrap and microwave on full power for 10 minutes.\nMake the stuffing for the pumpkin by mixing the remaining ingredients, adding sufficient cream to bind the mixture.\nRemove the pumpkin from the bowl with the water and place on a flat plate.\nFill the hollow with the stuffing and microwave on full power for a further 5 minutes.', 
'Recipes Printout.docx');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Udon and leek miso broth', 'Dinner', 
'Serves 2-3\n2 large leeks\nCanola oil spray\n2 tbsp miso paste\n2 cups vegetable stock\n2 tbsp soy sauce\n1 sheet sushi nori (optional)\n300g udon noodles\n300g extra firm tofu', 
'Oven at 220degrees & Saucepan with water over high heat.\nCut 2 Leeks into quarters, into baking tray @220 degrees for 22minutes, until golden and soft.\nBroth: 2 tbsp miso, vegetable stock 2 cups, 2tbsp soy sauce, 400ml water, sushi nori torn up into small bits. Whisk & simmer.\nBoil udon noodles 300g for 3minutes, noodles into serving bowls.\nTofu 300g cut into small cubes, simmer(low boil) for 2minutes. Fish out tofu Into serving bowls.\nShred the cooked leeks into small pieces, put into serving bowls.\nPour broth into serving bowls.', 
'Recipes Printout.docx');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Tamago and mushroom Donburi', 'Dinner', 
'Rice 150g\nMushrooms\n4 eggs\n2 tsp caster sugar\ncanola oil spray\n1/2 cabbage\nSushi nori sheet (optional)\nSalt\nMixing bowl, whisk\nBaking paper\nBaking tray\nCling film', 
'Oven 200degrees C; line baking tray with baking paper.\n150g rice, 300ml water into pot and high heat, bring to boil, cover lid, reduce heat to low, simmer for 9minutes.\nCut Mushrooms into bite size pieces, put onto baking paper as a single layer, light spray of canola oil, season with salt, into oven 220degrees C for 9minutes until golden/crisp.\n\nTamago:\nWhisk 4 eggs in a bowl, 2tbsp sugar, 1tbsp soy sauce.\nFrying pan, add 1/2 tbsp oil (or light spray) medium heat, once oil is shimmering tip 1/2 of egg mixture into pan. Allow egg to set for 1-2minutes, roll one edge to opposite to make a sausage shape, with eggroll still in pan, pour in rest of mixture, fry for another 1-2minutes until set, roll eggroll back over newly formed eggsheet to make even bigger eggroll, transfer to board for cutting.\n\nCook cabbage:\nCabbage into mixing bowl, cover with cling film microwave for 5-6minutes.\n\nMushrooms onto plate, cabbage onto plate, eggroll(tamago) onto plate or put all into a sushi nori sheet.', 
'Recipes Printout.docx');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Okonomiyaki with pickled cucumber salad', 'Dinner', 
'2 eggs\n30g flour\n2 tbsp soy sauce\n1/2 cabbage\n10g ginger\n3 tbsp mayonnaise\n1 tsp miso paste\n3 tbsp tomato ketchup\n1 tbsp allspice\n3 tbsp Canola oil\n150g mushrooms\n3 tbsp vinegar\n2 tbsp caster sugar\n1 cucumber\n2 sheets sushi nori\n5 Spring onion\nMixing bowl\nWhisk', 
'Oven 180C degrees.\n2 eggs, 30g flour, 1tbsp soy sauce, whisk; pancake batter consistency.\nThinly slice the 1/2 cabbage & 5 spring onion & 10g grated ginger throw into the bowl and mix everything to have an even coating.\n\nSauces:\n3tbsp mayonnaise, 1 tsp miso into small bowl.\nIn another small bowl, 3 tbsp ketchup, 1tbsp all-spice 1tbsp soy sauce.\n\nLarge Oven proof Pan with canola oil, on oven until smoking, then place mushrooms into chunks into pan for 4minutes (golden).\nAfter golden mushrooms, pour cabbage mixture into pan, cook for another 5minutes, then into oven for 5minutes (once can cut through cleanly = done).\nPut onto plates mushroom side up, put sauces on top of the okonomiyaki (mostly using the ketchup based sauce).\n\nSalad:\n3tbsp vinegar and 2 tbsp sugar into large mixing bowl, microwave for 90sec until sugar dissolves. Then use a vegetable peeler to cut ribbons from the cucumber into mixture, mix, put cucumber on side of plates.', 
'Recipes Printout.docx');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Mashed Sweet Potato', 'Dinner', 
'Sweet potato\ncling wrap\nmicrowaveable mixing bowl\nwater, salt and pepper', 
'1. Cut sweet potato into bite sizes, and add into large microwaveable mixing bowl with water, salt and pepper and cover with cling wrap.\n2. Microwave for 15 minutes.', 
'Recipes Printout.docx');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Thai Green Prawn and Edamame noodle soup', 'Dinner', 
'Prawns 400g\nThai Green Curry Paste 2 tbsp\nCoconut milk 400g\nEdamame beans 300g\nNoodles 200g\nVegetable oil 2 tbsp', 
'1. Medium heat Vegetable oil 2tbsp and Thai Green Curry Paste 2 tbsp. Fry for 2 minutes.\n2. Add 400g Coconut milk, mix and bring up to boil.\n3. Reduce heat to low and add in Prawns and Edamame, Poach for 6 minutes.\n4. Boil noodles.', 
'Recipes Printout.docx');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Pumpkin Chips', 'Dinner', 
'Aluminium Foil\nPumpkin\nHerbs', 
'1. Pre-heat Oven 200C.\n2. (remove seeds first) Cut Pumpkin into 3cm cubes and chuck onto foil lined tray.\n3. In Oven for 25minutes.', 
'Recipes Printout.docx');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Pumpkin Soup (Sharyn)', 'Soups', 
'Serves: 6\n2 kg pumpkin\n2 medium white onions\n2 red apples (skinned)\n3 chicken stock cubes\n1 teaspoon nutmeg\n1 teaspoon salt\n2 cups water\n2½ cups milk\nFreshly ground pepper to taste', 
'Peel and chop pumpkin.\nChop onions and apples.\nPlace in a heavy based saucepan.\nAdd stock cubes, seasonings and water. Bring to boil. Cover and simmer for 35 to 40 minutes until the pumpkin is tender.\nVitamise through a blender or rub through a sieve.\nBlend in milk.\nAdjust seasonings to taste.\nGarnish with sour cream and chopped chives.', 
'Recipes Printout.docx');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Vegetable Lasagne (Sharyn)', 'Dinner', 
'Serves: 8 to 10\n60 g [2oz] butter\n2 medium carrots, finely chopped\n2 stalks of celery, finely chopped\n1 medium green capsicum, chopped\n2 medium onions chopped\n2 medium zucchini, sliced\n440g can tomatoes, chopped\n1½ cups tomato puree\n2 bay leaves\n3 garlic cloves, finely chopped\n¼ cup parsley, chopped\n1 tablespoon chopped basil leaves\n1 teaspoon dried oregano crushed\nSalt and freshly ground black pepper to taste\n2 cups sliced mushrooms\n250g [8oz] lasagne noodles, cooked, rinsed and drained\n2 cups ricotta or cottage cheese\n250g [8oz] mozzarella cheese cut into thin pieces\n¼ cup grated parmesan cheese', 
'In a large saucepan melt butter or margarine.\nStir in carrots, celery, capsicum and onion. Cover and cook 10 minutes, stirring frequently.\nAdd zucchini, un-drained tomatoes and tomato puree and mix well.\nAdd bay leaves garlic, parsley, basil, oregano, salt and pepper. Cover and simmer 30 minutes.\nRemove cover and continue simmering 10 to 15 minutes more or until thickened to desired consistency.\nStir in sliced mushrooms, cook 5 minutes more.\nRemove from heat. Discard bay leaves.\n\nTo make up the lasagne:\nIn a greased 30 x 23 x 5cm baking dish, layer ⅓ of the noodles, vegetable sauce, Ricotta, and mozzarella. Repeat twice, ending with mozzarella. Sprinkle parmesan all over. Cover with foil. Place on a baking sheet. Bake in oven preheated to 180°C for 45 minutes.\nRemove foil and continue baking 10 minutes more until cheese is golden.\nRemove from oven and let stand 10 minutes before serving.', 
'Recipes Printout.docx');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Brownies-Macadamia Brownies (Sharyn)', 'Desserts', 
'From Cadbury Dark Cooking chocolate wrapper\n150g unsalted butter, chopped\n250g Dark cooking chocolate, chopped\n1½ cups caster sugar\n4 eggs, lightly beaten\n1 teaspoon vanilla essence\n1 cup plain flour, sifted\n½ cup sour cream\n1 cup macadamia nuts, cut in half', 
'Pre-heat oven to 160°C conventional or 140°C fan forced. Line a 20cm X30 cm slice pan with baking paper.\nCombine butter and chocolate in a medium saucepan; stir over low heat until the chocolate is just melted. Add sugar, egg, vanilla, flour, sour cream and nuts. Stir until well combined. Spread mixture into prepared pan.\nBake 35 minutes or until brownie forms and a crust forms on the outside. Allow to cool and slice.', 
'Recipes Printout.docx');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Easy Orange or Lemon Cake (Sharyn)', 'Desserts', 
'120 g [4 oz] butter\n1½ cups S-R flour\n1 cup sugar\n½ cup milk\n2 eggs\nGrated rind of 1 lemon or orange', 
'Melt butter.\nPut all other ingredients in a basin.\nAdd melted butter and beat for 5 minutes.\nPlace in a greased cake tin about 8 inches across and bake in a 350°F oven for about ½ hour.', 
'Recipes Printout.docx');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Lemon Delicious (Sharyn)', 'Desserts', 
'5 Small serves\nOven temperature 190C\nCooking time- 45 minutes\n1 tablespoon butter\n3/4 cup caster sugar\n1 tablespoon flour\n2 tablespoons S-R flour\n2 lemons- rind and juice (I only use 1 and a bit lemons)\n2 eggs, separated\n1 cup milk', 
'1. Collect ingredients\n2. mix butter and sugar\n3. Stir in flours, lemon juice and rind. Add egg yolks and milk. Beat well.\n4. Beat egg white until stiff. Fold into mixture. Pour into dish. ( I use a small casserole dish.)\n5. Stand dish in a baking dish of warm water about 3 centimetres deep Bake until set and lightly browned.\n6. Serve with cream or ice-cream.', 
'Recipes Printout.docx');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Scones (Sharyn)', 'Desserts', 
'3½ cups S-R flour\n½ level teaspoon salt\nPinch nutmeg\n60g butter\n¼ cup caster sugar\n1 egg\n350 ml milk [almost 1½ cups]\nFew drops each of lemon and vanilla essence', 
'Sift flour, salt and nutmeg into a mixing bowl.\nRub in the butter with the finger tips and then add the sugar and mix well.\nMake a well in the middle, and then add the egg, milk and flavouring essences and make into a soft dough.\nEmpty the dough out onto a lightly floured surface and knead slightly with a little extra S-R flour.\nRoll out the dough to 2cm thickness.\nCover the scones with a clean tea towel and leave them to “rest” for 1 hour.\nArrange closely on a greased baking tray. This lets the scones support one another as they rise.\nBefore baking, brush the tops of the scones with milk and then bake in a very hot oven [220°C] for about 20 to 25 minutes or until cooked.\nRemove from the oven and wrap in a clean tea towel to steam for 10 minutes.\nServe with jam and cream.', 
'Recipes Printout.docx');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Thelma Pumpkin Scones (Sharyn)', 'Desserts', 
'3 cups S-R flour\n1½ dessertspoon sugar\n¾ cup pumpkin cold [cooked, drained and mashed with no lumps]\n¾ teaspoon baking powder\nOrange juice or milk', 
'Rub butter into flour.\nAdd all the other ingredients and mix together.\nMake into scones and bake.\nGlaze with butter immediately out of the oven.\nFreeze immediately.', 
'Recipes Printout.docx');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Apple Cake by Wendy CCDC', 'Apple Cake by Wendy CCDC.doc', 
'4 tablespoons of very soft butter\n4 tablespoons caster sugar\n2 whole eggs, beaten\n1 teaspoon vanilla essence\n8 tablespoons of S-R flour [approximately]\n1 large can of pie apples\nSugar, cinnamon and ground coriander for sprinkling on top.', 
'Mix soft butter and sugar until smooth.\nAdd 2 whole eggs beaten and add vanilla essence.\nAdd about 8 tablespoons of S-R flour- just keep adding until it is firm but still softish.\nDivide mixture into two.\nGrease the round cake pan well and press one part of the mixture on the base.\nSpread the apple over the base. Sprinkle with sugar, to taste, cinnamon and ground coriander.\nArrange the other part of the mixture- usually it needs to be done in pieces at a time.\nCook in oven at 180° for 40 minutes or until golden brown.\nTurn out onto a plate. Spread the top with butter and sprinkle sugar and cinnamon.\nServe warm with cream or ice cream.', 
'Apple Cake by Wendy CCDC.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Apple Crumble', 'Apple Crumble.doc', 
'Fuji apples/ Golden delicious (Cut the same size)\n2 tablespoons honey\n2 tablespoons caster sugar\nSome self raising flour\nBrown sugar', 
'Put apples in a saucepan with 2 tablespoons honey, 2 tablespoons caster sugar, and some self raising flour.\nAdd brown sugar on top and gently mix in.\nCook at 180°C for 40 minutes.', 
'Apple Crumble.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Apricot Chocolate Truffles', 'Apricot Chocolate Truffles.doc', 
'1 cup rice bubbles\n½ cup desiccated coconut\n¼ cup dried apricots\n¼ cup chopped mixed peel\n¼ cup slivered almonds\n¾ cup sweetened condensed milk\n250g white chocolate chopped\n100g dark chocolate chopped\nGlaze cherries for decoration (three red bits and green leaves)', 
'Combine rice bubbles, coconut, apricots, peel and almonds. Add condensed milk. Stir until combined. Cover with plastic wrap and refrigerate till firm.\nShape heaped teaspoons of mixture into balls.\nPlace white chocolate into small heatproof bowl. Stand over bowl of simmering water until chocolate has melted.\nDip truffles into chocolate allow excess to run off. Refrigerate till set.\nRe-dip in dark chocolate if desired.\nDecorate the top with glaze cherries.', 
'Apricot Chocolate Truffles.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Beef Curry', 'Beef Curry.doc', 
'Serves: 6\n1.25kg skirt or chuck steak\n2 large onions, sliced thinly\n1 teaspoon grated fresh ginger\n3 cloves garlic, crushed\n2 tablespoons curry powder\n2 teaspoon salt\n½ teaspoon chilli powder\n1 teaspoon poppy seeds\n2 large tomatoes, peeled and chopped', 
'After trimming excess fat from meat, cut into 2.5cm [1 inch] cubes.\nGently fry onions, ginger and garlic in about 2 tablespoons oil until softened and onions are lightly tinted.\nAdd curry powder, salt and chilli powder, stir over low heat for 2 to 3 minutes.\nAdd the meat and fry, stirring for another 3 minutes.\nStir in the poppy seeds, tomatoes and ⅓ cup warm water. Cover pan and cook over very low heat for about 2 hours, adding more water [very little] if necessary.', 
'Beef Curry.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Beef Sate', 'Beef Sate.doc', 
'Serves: 6\n1 kg [2 lb] rump steak\n2 tablespoons tomato paste\n3 tablespoons tomato sauce\n3 teaspoons curry powder\n2 teaspoons chilli powder\n1 teaspoon garam masala\n2 teaspoon cumin\n1 clove garlic\n3 tablespoons white vinegar\nSalt and pepper\n1 teaspoon soya sauce\n1 tablespoon water\n3 tablespoons oil, extra\n\nSate Sauce:\n4 tablespoons peanut butter [or 1½ tablespoons]\n½ teaspoon chilli powder\n⅓ cup brown malt vinegar\n3 tablespoons of sugar\n1 cup water\n30g [1oz] butter\n1 medium onion\n1 teaspoon soya sauce\nSalt and pepper', 
'Remove all fat from the meat. Cut meat into 1 cm cubes.\nPut tomato paste, tomato sauce, curry powder, chilli powder, garam masala, cumin, crushed garlic, vinegar, salt, pepper, oil, soya sauce, and water into a bowl. Mix well.\nAdd meat, Mix well. Let stand overnight or several hours.\nDrain marinade from meat. Reserve marinade for sauce.\nThread meat onto bamboo skewers.\nPut under hot grill. Grill until golden brown and cooked through. Turn skewers frequently, brushing with extra oil. Serve with sate sauce.\n\nSATE SAUCE METHOD:\nHeat butter in pan. Add peeled and finely chopped onion. Saute gently until onion is golden brown.\nAdd remaining ingredients and mix well. Add reserved marinade, stir until combined.\nBring to boil. Boil uncovered for 5 minutes or until the sauce is thick.', 
'Beef Sate.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Boeuf en Daube Provençale', 'Boeuf en Daube Provençale.doc', 
'Serves 4\n2 pounds lean beef, cut in 2 1/2-inch cubes\n1 pound salt pork\n1/4 pound pork skin\n3 tablespoons butter\nFlour\n2 large onions, thinly sliced\n1 clove garlic, chopped\n3 carrots, thinly sliced\nPinch of ground cloves\n1 teaspoon thyme\n1 bay leaf\n1/4 cup cognac, warmed\n1 bottle red Burgundy or California Pinot Noir\n1/2 cup water\nSalt, freshly ground black pepper', 
'Cube salt pork and cut pork skin into small rounds. When browned, remove from pan. Add butter to rendered fat. Flour beef lightly and brown in butter-fat mixture, turning to brown evenly on all sides. Return salt pork to pan with pork skin, onions, garlic, carrots, ground cloves, thyme and bay leaf. Pour on warmed cognac and ignite. Extinguish flames by pouring on wine and water. Bring to a boil, add salt and pepper to taste. Cover pan and simmer on low heat (or cook very slowly in a 275°F. oven) for 8 hours. The liquid must never return to the boiling point. Serve with parsleyed boiled potatoes.', 
'Boeuf en Daube Provençale.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Boiled Pineapple fruit cake [Maureen]', 'Boiled Pineapple fruit cake [Maureen].doc', 
'One 15 oz can crushed pineapple, undrained\n4 oz butter\n1 cup sugar\n½ pound sultanas\n¼ pound chopped dates\n¼ pound chopped glazed cherries\n1 level teaspoon bicarb of soda\n2 eggs\n1 cup S-R flour\nPinch salt', 
'Simmer undrained crushed pineapple, butter, sugar, sultanas, chopped dates and cherries in a saucepan for 15 minutes. Add bicarb of soda, stir and then cool.\nBeat eggs and stir into cooled fruit mixture. Lightly fold in sifted flours and salt.\nTurn into an 8 inch round cake tin lined with brown paper and then white paper.\nBake at 350° for 1 ¾ hours.', 
'Boiled Pineapple fruit cake [Maureen].doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Cake- Best Ever Chocolate Cake', 'Cake- Best Ever Chocolate Cake.doc', 
'½ cup cocoa\n½ cup boiling water\n185gm butter\n1 ½ cups of caster sugar\n3 eggs\n2 cups S-R flour [or 1 ¾ cups S-R and ¼ cup plain flour]\n¼ level teaspoon bicarbonate of soda\n¾ cup milk\n1 tablespoon vanilla', 
'Mix cocoa with boiling water in a small bowl, cool.\nGrease a large baking dish 27cm X 32 cm and line the base with Gladbake (or 2 X 20cm sandwich tins lined with baking paper).\nCream butter and sugar until light and fluffy. Add eggs one at a time and beat in well.\nSift flour and soda and gently stir into the creamed ingredients, then add milk and vanilla.\nWhen well mixed, gradually stir in the cocoa mixture, mixing thoroughly. (If it curdles, do not worry).\nPour into prepared cake tin and bake in a moderate oven for 30 to 35 minutes. Test with a skewer. Stand 5 minutes before turning out.', 
'Cake- Best Ever Chocolate Cake.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Cake- Pecan Sour Cream Cake', 'Cake- Pecan Sour Cream Cake.doc', 
'250gm [8 oz] butter\n¾ cup sugar\n2 x 60g eggs\n1 teaspoon vanilla essence\n300ml sour cream\n2 cups plain flour\n1 teaspoon bicarbonate of soda\n1 teaspoon baking powder\n½ teaspoon salt\n\nTopping:\n½ to ¾ cup pecans\n2 tablespoons brown sugar\n½ teaspoon cinnamon', 
'Beat together butter and sugar until creamy. Add eggs, one at a time, beating well after each addition, then add the vanilla essence. Whisk sour cream until smooth and stir in. Sift together flour, bicarbonate of soda, baking powder and salt and fold in.\nPour half into a greased deep 20cm cake tin, sprinkle with half the combined topping ingredients. Cover with the remaining half of the cake mixture, sprinkle rest of topping over, pressing pecans in lightly.\nBake in a moderate oven for one hour or until done when tested. Let stand for 10 minutes before turning out.', 
'Cake- Pecan Sour Cream Cake.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Cake-Layer Strawberry Mocha Torte', 'Cake-Layer Strawberry Mocha Torte.doc', 
'Cake:\n125gm butter, softened\n1 cup caster sugar\n2 eggs\n½ cup cocoa\n¾ cup water\n¼ cup Tia Maria\n\nFilling:\n250gm ricotta cheese\n2 tablespoons sugar\n60g finely chopped mixed peel\n125gm strawberries, chopped\n\nCoffee Cream:\n2 tablespoons instant coffee powder\n1 teaspoon hot water\n3/4 cup thickened cream\n125 gm strawberries, sliced as decoration', 
'Cake: Combine butter, sugar, eggs, sifted flour, cocoa, and water in a small mixing bowl. Beat with an electric mixer until smooth and pale. Pour into a greased and base-lined 23cm round cake pan. Bake in a moderate oven for 45 minutes. Turn onto wire rack to cool upside down. Cut cake into 3 even layers and brush each with Tia Maria.\nFilling: Combine ricotta cheese, sugar, chopped mixed peel, and chopped strawberries.\nAssemble: Place a layer of cake onto a serving plate, spread with half the filling. Repeat layers. Cover and refrigerate.\nCoffee Cream: Dissolve coffee in water. Whip combined cream and coffee mixture until soft peaks form. Spread on cake and decorate with sliced strawberries.', 
'Cake-Layer Strawberry Mocha Torte.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Carol-Baked Fish Fillets', 'Carol-Baked Fish Fillets.doc', 
'Fish fillets\n¼ cup lemon juice\n1 teaspoon grated lemon rind\n2 cup breadcrumbs [fresh]\n1/2 teaspoon mustard\n1 Tablespoon Parmesan\n1 cup cheddar cheese, grated\n3 spring onions, sliced\nSalt and pepper\nWater and a little olive oil', 
'Layer fish fillets in a shallow dish. Pour on the lemon juice and leave sit while preparing the breadcrumb mixture.\nCombine breadcrumbs, rind, mustard, parmesan, cheddar cheese, spring onions, salt, and pepper. Make slightly moist with water and a little olive oil.\nCover fish with layer of breadcrumb mixture.\nBake 20 minutes in a mod-hot oven until the topping is brown and crisp.', 
'Carol-Baked Fish Fillets.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Carol-Grilled Tuna with Thai Cucumber Salad', 'Carol-Grilled Tuna with Thai Cucumber Salad.doc', 
'Serves 4\n2 lebanese cucumbers\n1 tablespoon sugar\n2 tablespoons white wine vinegar\n1 red chilli, finely chopped\n2 spring onions, thinly sliced\n2 tablespoon coriander leaves\n2 teaspoon fish sauce\n1 tablespoon lime juice\n⅓ cup chopped roasted peanuts\n4 x 200g tuna fillets\nSalt and freshly ground pepper\nVegetable oil\nLime wedges for garnish', 
'Salad: Cut the cucumbers in half and slice thinly into rounds. Combine with the rest of the ingredients down to the tuna on the list.\nTuna: Season well and barbeque or grill until they are medium rare - about 2 minutes on each side on high heat. Serve each tuna fillet with a portion of salad and a lime wedge.', 
'Carol-Grilled Tuna with Thai Cucumber Salad.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Carol''s Chocolate Plum Puddings', 'Carols Xmas puddings.doc', 
'SERVES 6\n125gm (4oz) dark cooking chocolate, chopped\n90gm (3oz) butter, chopped\n1/2 cup (55g) almond meal\n3 eggwhites, whisked lightly\n1/4 teaspoon mixed spice\npinch ground cloves\n1 1/2 tablespoons plain flour, sifted\n1/2 teaspoon baking powder\n1/3 cup (75g) castor sugar\n1/2 cup (120g) chopped pitted prunes\n1 1/2 tablespoons marsala\nvanilla ice-cream to serve\ncocoa powder for dusting', 
'Preheat oven to 150''C (300''F). Place the chocolate & butter in a saucepan over low heat & stir until melted & combined. Set aside.\nPlace the almond meal, eggwhites, mixed spice, cloves, flour, baking powder, sugar, prunes & marsala in a bowl. Pour in the chocolate mixture & stir until fully combined.\nSpoon the mixture into six 1/2 cup capacity greased metal dariole moulds. Place on a baking tray & cook for 30 minutes or until springy to touch. Cool in the tins for 5 minutes before removing. Serve warm sitting on their small ends with ice-cream and cocoa powder.', 
'Carols Xmas puddings.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Carrot Cake', 'Carrot Cake.doc', 
'¾ cup oil\n½ cup chopped walnuts\n1 cup sugar\n1 teaspoon mixed spice\n2 eggs\n½ cup plain flour\n½ teaspoon bicarb of soda\n1½ cups grated carrot\n½ cup S-R flour\n1 teaspoon vanilla\n\nLemon Cream Cheese Icing:\n123gm softened cream cheese\n2 cups of icing sugar\n1 teaspoon lemon juice', 
'Beat sugar and eggs together. Stir in the oil and carrot and then the dry ingredients. Spoon into a 20cm greased round tin. Bake for 1 hour in a moderate oven. Ice with lemon cream cheese icing when cold.', 
'Carrot Cake.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Chicken Wings Baked [Sharyn]', 'Chicken Wings Baked [Sharyn].doc', 
'Chicken wings\nLemon juice\nCoriander\nPaprika\nSoya sauce\nCooking oil\nSalt', 
'Put chicken wings in a baking dish. Sprinkle lemon juice over. Sprinkle with coriander, paprika and rub in. Sprinkle with soya sauce. Bake in a moderate oven.\nWhen half cooked, put lemon juice, soya sauce and also cooking oil over chicken wings and sprinkle with salt. Then continue cooking. Serve.', 
'Chicken Wings Baked [Sharyn].doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Chicken- Tangy lemon chicken', 'Chicken- Tangy lemon chicken.doc', 
'Serves 4\n1 medium cooked chicken (or raw chicken breast cut up)\n2 tablespoons polyunsaturated oil\n3 teaspoons grated ginger\n3 tablespoons lemon juice\n1 cup [250ml] chicken stock\n1½ tablespoons honey\n2 tablespoons sugar\n1 tablespoon cornflour blended with 1 tablespoon water\n2 shallots chopped', 
'Cut chicken into serving pieces. Heat oil in frying pan or wok and stirfry chicken for 2-3 minutes. Remove and keep warm.\nStir in ginger and cook for 1 minute. Pour in combined lemon juice, stock, honey, and sugar. Add blended cornflour to pan and cook for 1-2 minutes until the sauce has thickened.\nReturn chicken to pan and heat through gently. Serve sprinkled with shallots. (Goes well with rice and salad).', 
'Chicken- Tangy lemon chicken.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Chocolate Brownies Recipe', 'Chocolate Brownies Recipe.doc', 
'24 Slices\n1/3 cup S-R flour\n1/2 cup cocoa\n1½ cups sugar\n1 cup of chopped dark chocolate chips\n100g chopped walnuts\n125 g butter, melted\n4 lightly beaten eggs\n2 teaspoons vanilla essence', 
'Grease Slice pan and line with baking paper. Preheat Oven at 180°.\nSift Flour and cocoa powder into a large bowl. Add in sugar, chocolate bits and walnuts. Mix thoroughly.\nMake a well in the center of dry ingredients. Add melted butter, eggs and vanilla essence into well.\nMix all ingredients thoroughly until mixture turns thick and creamy.\nPour into pan and smooth surface. Bake for 40 minutes.\nCool for 10 minutes and fridge them for about 2 hours. Slice and serve!', 
'Chocolate Brownies Recipe.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Chocolate Fruit cake slice [Maureen]', 'Chocolate Fruit cake slice [Maureen].doc', 
'250g dates, finely chopped\n¾ cup brown sugar\n½ cup water\n125g butter\n¾ cup choco pieces\n2 eggs beaten\n1 ¼ cup plain flour\n¾ level teaspoon bicarb of soda\nGood pinch salt\n½ cup of orange juice\n½ cup milk\n1 cup chopped walnuts\n\nLemon Icing:\n1 ½ cups sifted icing sugar\n1 tablespoon soft butter\n1 teaspoon grated lemon rind\n2 tablespoons lemon juice\nWalnuts to garnish', 
'Combine dates, sugar, water and butter in a saucepan. Stir over low heat until dates are soft. Cool slightly and stir in chocolate. Add well beaten eggs. Then add sifted dry ingredients, alternating with orange juice and milk. Fold in nuts.\nSpread into a greased lined tin 28 X 18 cm. Bake at 180°C for 35 to 45 minutes. Cool in tray.\nIcing: Mix icing sugar, butter, lemon rind and juice together. Stir over low heat for a minute. Spread over slice and garnish with walnuts.', 
'Chocolate Fruit cake slice [Maureen].doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Chocolate Ripple Cake [Maureen]', 'Chocolate Ripple Cake[Maureen].doc', 
'½ pound chocolate Ripple biscuits\n1 teaspoon castor sugar\n½ pint cream\nVanilla essence\nChopped nuts', 
'Add sugar and a drop of vanilla essence to cream and whip until it is very stiff.\nJoin biscuits together with the cream.\nAllow the cake to stand at least 6 hours to set. Top with chopped nuts.', 
'Chocolate Ripple Cake[Maureen].doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Chocolate Rum Truffles [Maureen]', 'Chocolate Rum Truffles [Maureen].doc', 
'4 oz butter\n4 oz icing sugar\n2 oz cocoa\n2 tablespoons rum\n6 oz coconut\n1 teaspoon vanilla essence\n2 cups chopped mixed fruit [dates, raisins, cherries, or glazed ginger]\nChocolate nonpareils', 
'Beat the butter and sifted icing sugar to a cream, then beat in cocoa adding a little rum to moisten.\nBeat the remainder of the rum. Then stir in the coconut, vanilla essence and chopped fruit.\nTake spoonfuls and roll into balls before tossing in chocolate nonpareils.', 
'Chocolate Rum Truffles [Maureen].doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Christmas Punch [Non alcoholic]', 'Christmas Punch [Non alcoholic].doc', 
'3 oranges\n3 lemons\nHandful mint\n1 cup sugar\n1 cup lime juice cordial\n3 bottles ginger ale\n3 bottles lemonade\n5 cups water\nIce cubes', 
'Slice oranges and lemons and place in a large bowl. Add finely chopped mint. Add sugar and bruise fruit until the juices begin to run. Allow to stand for 1 hour.\nAdd lime juice and water.\nJust before serving add dry ginger, lemonade and ice cubes.', 
'Christmas Punch [Non alcoholic].doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Christmas Roasted Vegies', 'Christmas Roasted Vegies.doc', 
'Serves 8\n2 beetroot, trimmed and washed\n2 medium sweet potatoes, cut in chunks\n2 parsnip, cut into quarters and halved\n2 red onions, cut into quarters\n½ cauliflower, broken into florets\n2 or 3 whole red chillies\nOlive oil spray\nBeetroot leaves shredded\n\nMustard Dressing:\n1 ½ tablespoon whole grain mustard\n2 teaspoons Dijon mustard\n1 tablespoon sherry\n2 tablespoons of lemon juice\nSalt and pepper\n125 ml olive oil', 
'Pre-heat oven to 200°C. Wrap the beetroot in foil and roast on a tray for 25 minutes. Spray the remaining vegetables with olive oil and roast until golden.\nRemove beetroot, peel skins, cut into eighths, and drizzle with some dressing.\nCool other vegetables slightly, place in bowl, drizzle with dressing and toss with beetroot leaves. Add beetroot wedges just before serving.\nDressing: Shake all ingredients in a jar until creamy.', 
'Christmas Roasted Vegies.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Christmas – Hard sauce', 'Christmas-Hard sauce.doc', 
'2 tablespoons butter\n3 tablespoons icing sugar\n1 tablespoon brandy\n½ teaspoon vanilla\nNutmeg for dusting', 
'Collect ingredients. Cream butter and sugar until light and fluffy. Gradually add brandy and vanilla. Place in a small dish and dust with nutmeg.', 
'Christmas-Hard sauce.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Cottage Cheese and Herb Loaf', 'Cottage Cheese and Herb Loaf.doc', 
'Serves: 6\n½ cup finely chopped onion\n30g butter\n1 tablespoon chopped parsley\n500g cottage cheese\n1 cup finely chopped celery\n1 cup rolled oats or breadcrumbs\n3 eggs, beaten\n1 teaspoon vegetable salt\n1 teaspoon mayonnaise\nSesame seeds\n\nSEV Modifications:\n250g cottage cheese, parmesan, tasty cheese, fresh basil, black pepper, capsicum, mushrooms, poppy seeds.', 
'Gently fry onion in butter until soft. Remove from heat, sprinkle rosemary over and let stand.\nPlace cottage cheese in mixing bowl and add sautéed onion and all remaining ingredients except sesame seeds. Mix well.\nPour mixture into greased loaf tin and sprinkle sesame seeds over the top.\nBake at 180°C for 1 hour or until firm and golden.', 
'Cottage Cheese and Herb Loaf.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Couscous-Lamb and vegies', 'Couscous-Lamb and vegies.doc', 
'1 lamb shoulder, boned\n3 tablespoons olive oil\n2 onions, cut in wedges\n3 cloves garlic, sliced\n2 sticks cinnamon\n¼ teaspoon saffron\n2 teaspoons salt\n½ teaspoon ground black pepper\n2 cups chick peas\n2 large carrots\n500g pumpkin\n1 medium sweet potato\n1/3 cup chopped fresh coriander\n500gm zucchini\n½ cup seedless raisins\n2 cups couscous', 
'Trim fat from lamb and cut into cubes. Brown lamb in 2 tbsp olive oil in batches; remove.\nAdd remaining oil and fry onions and garlic until golden. Return lamb, add water to come level with meat, and add cinnamon. Toast saffron, dissolve in boiling water, add to pan with salt, pepper, and chick peas. Simmer for 1.5 hours.\nAdd carrots, pumpkin, sweet potato, coriander, and raisins. Simmer 25 minutes, adding zucchini 10 minutes before the end.\nPrepare couscous as directed. Pile couscous on a dish, ladle stew in the centre.', 
'Couscous-Lamb and vegies.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Crustless Quiche', 'Crustless Quiche.doc', 
'1½ cups milk [or ½ cup milk, 1 cup cream]\n3 eggs\n1 tablespoon melted butter\n3 rashes bacon, chopped\n1 small onion, finely chopped\n½ cup S-R flour, sifted\nSalt and pepper\n1 cup cheddar cheese', 
'Combine milk, eggs, butter, salt, and pepper and beat.\nIn a separate mixing bowl, stir together bacon, onion, flour, and cheese.\nPour egg mixture into bacon mixture. Stir.\nPour into a medium quiche dish and bake at 200ºC for 40 minutes or until set.', 
'Crustless Quiche.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Eggplant casserole', 'Eggplant casserole.doc', 
'Eggplant\nBasil\nBlack pepper\nBeans', 
'Ingredients and instructions structurally matching the dynamic placeholder text notes.', 
'Eggplant casserole.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('FLAN- Savoury Pumpkin Flan', 'FLAN Savoury pumpkin.doc', 
'Serves 4\n4 sheets of filo pastry\n2 tablespoon polyunsaturated oil\n2 rashes bacon, chopped\n½ medium onion, chopped\n250g pumpkin, cooked and mashed\n1½ cups grated tasty cheese\n2 eggs, separated\n2 tablespoons cream or yoghurt\nBlack pepper\nPinch chilli powder\n1 tablespoon fresh parsley', 
'Brush each layer of pastry with oil and fold in half to get 8 layers total. Line an 18cm flan dish.\nCook bacon and onion until crisp. Combine with pumpkin, cheese, egg yolks, and cream. Season with pepper and chilli powder.\nBeat egg whites until stiff peaks form. Fold into pumpkin mixture, spoon into pastry case, sprinkle with parsley. Bake at 200°C for 30 minutes.', 
'FLAN Savoury pumpkin.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Fluffy Savory Omelette', 'Fluffy Savory Omelette.doc', 
'Serves 1\n2 eggs\n3 shakes of pepper\n½ teaspoon salt\n2 teaspoons butter\nGrilled or fried bacon\nParsley sprigs\nChampignons, bacon, tomato filling', 
'Separate egg whites from yolks. Add pepper and water to egg yolks and beat until creamy. Beat egg whites and salt until stiff; fold yolks into whites.\nMelt 1 tsp butter in pan, wipe out. Melt remaining butter, pour in mixture. Cook slowly until brown underneath.\nPlace under hot griller until top is set. Cut almost through centre, fold over, and serve with bacon and parsley.', 
'Fluffy Savory Omelette.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Ginger Fluff Sponge', 'Ginger_Fluff_Sponge[1].doc', 
'4 eggs\n¾ cup castor sugar\n½ cup cornflour\n2 dessert spoons plain flour\n2 teaspoon ground ginger\n2 teaspoon cinnamon\n1 teaspoon cocoa\n1 teaspoon cream of tartar\n½ teaspoon bicarb of soda\n1 dessertsp golden syrup\nCream and lemon icing for filling/topping', 
'Separate egg whites and beat till stiff. Whisk egg yolks gently and stir into whites. Sift dry ingredients twice and fold into egg mixture. Add golden syrup.\nPlace in two sandwich pans and bake 15-20 minutes in a moderate oven. Fill with cream and top with lemon icing.', 
'Ginger_Fluff_Sponge[1].doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Harissa Sauce for Couscous', 'Harissa Sauce for Couscous.doc', 
'50g fresh hot red chillies or 20g dried chillies\n3-4 cloves garlic\n1 teaspoon ground coriander\n1 teaspoon ground cumin\n1 teaspoon dried mint leaves\n1 teaspoon salt\n2 tablespoon chopped fresh coriander\nOlive oil', 
'Snip off stems and remove seeds from chillies (leave seeds for hotter sauce). If using dried, soak in boiling water for an hour, then drain and reserve water.\nPut chillies and all other ingredients into a blender. Puree to a paste, using a little soaking water.\nTurn into a small glass jar, cover top with a thin layer of olive oil and refrigerate.', 
'Harissa Sauce for Couscous.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Jam drop biscuits- Maureen’s recipe', 'Jam drop biscuits.doc', 
'2 cups flour\nPinch salt\n¾ cup sugar\n1 teaspoon cream of tartar\n½ teaspoon bicarb of soda\n½ cup butter\n2 eggs\nJam for filling', 
'Beat butter and sugar to a cream, add eggs, then flour mixture. Make into small balls. Place on baking tray, press down in the centre and fill with jam.\nBake at 350ºF on the top shelf on a paper-lined tray for 7 minutes, turn tray, and bake for 5 minutes longer.', 
'Jam drop biscuits.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Kaya Toast', 'Kaya Toast.txt', 
'Eggs (room temperature)\nBread\nKaya jam\nHot water', 
'Cook at 19C for 9 minutes using room temperature eggs and pre-heated bowls with hot water.', 
'Kaya Toast.txt');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Lamb Cutlets with Herbed Barbeque Sauce', 'Lamb Cutlets with Herbed Barbeque Sauce.doc', 
'Serves 4\n8 lamb cutlets\n1 tablespoon lemon juice\n1 level tablespoon honey\n2 level tablespoons tomato sauce\nGarlic salt and black pepper\nFew sprigs fresh rosemary\n\nFrench Beans:\n250 g green beans\n1 teaspoon butter\nsalt', 
'Trim fat from cutlets. Combine lemon juice, honey, and tomato sauce on a plate. Dip cutlets to coat. Sprinkle with garlic salt, pepper, and rosemary leaves.\nMicrowave on full power for 8 to 10 minutes. Cover with foil. Return sauce to microwave uncovered for 1 minute, skim fat, and pour over cutlets.\nBeans: Chop beans to 2cm, place in microwave-safe bowl with butter and salt (no water). Cover and microwave on full power for 7 minutes.', 
'Lamb Cutlets with Herbed Barbeque Sauce.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Lamb in Pastry by Margaret Fulton', 'Lamb in Pastry by Margaret Fulton.doc', 
'90g butter\n6 lamb kidneys, sliced\n½ cup Madeira\n125g mushrooms, chopped\n1 teaspoon fresh thyme and tarragon\nSalt and pepper\n1 leg of baby lamb, boned\n250g frozen puff pastry, thawed\n1 egg, beaten', 
'Heat butter and sauté kidneys for 2 minutes. Add Madeira, mushrooms, and herbs; simmer 3 minutes and cool.\nStuff lamb with kidney mixture, re-shape, and sew with white thread. Rub with butter and bake at 200°C for 20 minutes. Let become cold and remove thread.\nRoll pastry thin, wrap the lamb, and seal with beaten egg. Decorate with pastry trimmings. Refrigerate 30 minutes. Brush with egg and bake at 230°C for 10 minutes (add extra time for Australian lamb).', 
'Lamb in Pastry by Margaret Fulton.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Lamingtons [Maureen]', 'Lamingtons [Maureen].doc', 
'Cake pieces\n1 pound sifted icing sugar\n3 tablespoons cocoa\n4 tablespoons hot water\n½ teaspoon vanilla\nCoconut', 
'Sift sugar with cocoa and mix with hot water and vanilla. Heat gently over low heat.\nDip cake pieces into icing and then coat completely with coconut.', 
'Lamingtons [Maureen].doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Lenten Moussaka', 'Lenten Moussaka.doc', 
'Serves: 6 to 8\n315g chick peas\n2 small eggplants [500g each]\nSalt and olive oil\n2 onions, sliced\n1 kg tomatoes, peeled and chopped\n3 tablespoons chopped parsley\n250ml water\n1 egg\n125ml yoghurt\nBrown lentils, marjoram, thyme (optional additions)', 
'Soak chick peas overnight, then boil in fresh water for 2 hours until tender. Cut eggplant into 5cm cubes, salt in a colander for 30 minutes, then drain.\nFry eggplant in oil for 5 minutes; place in casserole. Fry onion, place on eggplant, then cover with chick peas. Mix tomatoes with parsley, salt, and pepper; place on top. Pour water over.\nBeat egg with yoghurt, pour on top, and bake at 190ºC for 45 minutes.', 
'Lenten Moussaka.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Lime dipping sauce with seared Tuna', 'Lime dipping sauce with seared Tuna.doc', 
'Dipping Sauce:\n3 tbsp lime juice, 2 tbsp rice wine vinegar, 1 tbsp sweet chilli sauce, 2 tsp sesame oil, 2 tsp fish sauce.\n\nTuna:\nJuice of 2 limes, 2 tbsp sweet chilli sauce, 1 tbsp light soya sauce, 4 x 200g tuna steaks, 2 tsp olive oil.\nServing: 3 Lebanese cucumbers in ribbons, extra sliced lime.', 
'Sauce: Combine all dipping sauce ingredients together.\nTuna: Combine lime juice, sweet chilli, and soya sauce. Marinate tuna in fridge for 30 minutes. Remove tuna, heat pan with olive oil, and cook tuna for 1 minute on each side. Slice thinly, arrange with cucumber ribbons, and drizzle with dipping sauce.', 
'Lime dipping sauce with seared Tuna.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Maureen’s Sponge', 'Maureens Sponge.doc', 
'4 eggs\n¾ cup caster sugar\n3/4 cup cornflour\n1 tablespoon custard powder\n½ teaspoon soda\n1 teaspoon cream of tartar\n½ teaspoon vanilla essence\nPinch of salt', 
'Separate eggs. Beat whites with salt until stiff. Add sugar a little at a time while beating. Add egg yolks and beat in.\nSift dry ingredients 3 times and fold in, adding vanilla.\nPour into 2 large sandwich tins and bake for 25 minutes at 325° to 350°F.', 
'Maureens Sponge.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Maureen’s pavlova', 'Maureens pavola.doc', 
'4 whites of eggs\n8 oz caster sugar\n1 teaspoon vinegar\n½ teaspoon vanilla\n1 level dessertspoon cornflour\nCold water', 
'Preheat electric oven to 400ºF.\nBeat egg whites for 5 to 6 minutes. Gradually add sugar, vinegar, and vanilla. Beat until stiff. Fold in sifted cornflour lightly.\nWet a plate with cold water and put mixture on it.\nTurn oven down to 250ºF, place pavlova in, and bake undisturbed for 1½ hours.', 
'Maureens pavola.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Maureen’s Simplicity Chocolate Cake', 'Maureens simplicity chocolate cake.doc', 
'1 large cup of S-R flour\nPinch salt\n2 level table spoon cocoa\n½ cup milk\n1 cup castor sugar\n½ teaspoon vanilla\n3 tablespoon butter\n2 eggs', 
'Melt butter. Place all ingredients in a bowl and pour melted butter over. Mix well. Bake in a moderate oven for 30 minutes.', 
'Maureens simplicity chocolate cake.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Mike’s Slice', 'Mikes slice.doc', 
'Makes 24\nBase:\n4 oz butter, ½ cup sugar, 1 teaspoon golden syrup, 1 cup S-R flour, ¾ cup coconut.\n\nTopping:\n1 egg white, 2oz glace cherries, 2oz unsalted peanuts, ½ packet choco bits.', 
'Base: Cream butter and sugar. Add golden syrup, then flour. Fold in coconut. Spread in a greased 11 X 7 inch tray. Mark 3 strips.\nTopping: Brush base lightly with egg white. Arrange cherries, nuts, and chocolate bits on top.\nBake at 350°F for 20 minutes. Cut into finger lengths when cold.', 
'Mikes slice.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Mini Quiches', 'Mini Quiches.doc', 
'Makes 24\n2 sheets ready rolled puff pastry\n1 onion, finely chopped\n1-2 rashes bacon, chopped\n1/2 cup grated cheese\n2 eggs\n1/2 cup cream\nSeasoning to taste', 
'1. Cut 24 pastry rounds using a 6.5cm cutter; line patty tins.\n2. Divide onion, bacon, and cheese into the cases.\n3. Combine eggs, cream, and seasoning; beat with a fork.\n4. Pour carefully into cases.\n5. Bake in a hot oven for 15-20 minutes until golden.', 
'Mini Quiches.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Moussaka-Eggplant moussaka with Meat', 'Moussaka-Eggplant moussaka with Meat.doc', 
'Serves 6-8\n1 kg eggplant, oil\n\nMeat Sauce:\n1 onion, 2 cloves garlic, 2 tbsp oil, 1 kg ground beef, 1 cup peeled tomatoes, 2 tbsp tomato paste, ½ cup white wine, 2 tbsp parsley, 1 tsp sugar, ¼ tsp cinnamon, salt and pepper.\n\nCream Sauce:\n¼ cup butter, 1/3 cup flour, 2 cups milk, 1/8 tsp nutmeg, ¼ cup parmesan, 1 egg.', 
'Dégorge and fry eggplant slices. Fry onion and garlic, add meat to brown, then add remaining meat sauce ingredients; simmer 30 minutes.\nCream Sauce: Melt butter, stir in flour for 2 mins, add milk, bring to boil stirring. Remove from heat, add nutmeg, 1 tbsp cheese, salt, pepper. Stir in beaten egg.\nLayer eggplant and meat sauce in a dish. Pour cream sauce on top, sprinkle with remaining cheese. Bake 1 hour in a moderate oven.', 
'Moussaka-Eggplant moussaka with Meat.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Okonomiyaki (Hiroshima)', 'Okonomiyaki (Hiroshima).txt', 
'Batter (unspecified quantity)\nShredded Cabbage (~150g)\nTempura Crisps\nProtein (squid tempura/chicken)\nSpring onion, Beansprouts\nFish powder, Pork belly (3 strips)\nNoodles (1 bag), Dashi (2 rounds)\nEgg (1), Okonomiyaki sauce, Mayo, Seaweed bits', 
'At edge of grill: Spread 80% ladle of batter into a thin hand-sized circle. Move to centre.\nLayer cabbage, tempura crisps, protein, spring onion, beansprouts, fish powder, and pork belly strips. Drizzle remaining batter. Flip over.\nPrep noodles: Drop bag on grill, add 2 rounds of dashi, loosen, and shape into a circle. Place okonomiyaki on noodles.\nCrack egg, spread circle, place okonomiyaki on top while wet. Flip entire assembly, dress with sauce, mayo, seaweed, and eat.', 
'Okonomiyaki (Hiroshima).txt');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Paella', 'Paella.doc', 
'250 g chicken\n¼ cup olive oil\n1 rasher bacon\n1 onion\n2 tomatoes\n1 green pepper\n3 cloves garlic\n1 cup rice\n1 tsp salt\n2-3 cups chicken stock\n1 cup peas\n125g French beans\n½ diced crayfish\n1 cup prawns\n½ cup mussels\n⅛ tsp saffron\n6 olives', 
'Heat oil, fry chicken until brown, remove. Sauté bacon, onion, tomatoes, pepper, and garlic for 2 mins. Add rice and salt.\nAdd ¾ of the stock, boil until absorbed. Add remaining stock, simmer 15 mins until rice is cooked. Add cooked peas, beans, prawns, crayfish, mussels, and saffron to color.\nMix gently and serve within 10 minutes.', 
'Paella.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Pancakes-Drop Scones', 'Pancakes-Drop Scones.doc', 
'Makes 24\n1½ cups S-R flour\n3 tablespoons sugar\n1 egg, beaten\n¾ cup milk\n1 tablespoon butter', 
'Mix flour and sugar, make a well. Add milk to egg and pour into well; beat gradually. Heat pan, grease with butter, drop spoonfuls of mixture. Turn when bubbles appear. Cover with a clean towel when cooked to keep soft.', 
'Pancakes-Drop Scones.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Pasta with Fresh Basil and Chilli Pesto', 'Pasta with Fresh Basil and Chilli Pesto.doc', 
'Serves 4\n275g spaghetti\n1 cup fresh basil leaves\n1 small red chilli\n2 cloves garlic\n¼ cup pine nuts, toasted\n1/3 cup grated parmesan cheese\n100ml olive oil', 
'Cook spaghetti in boiling salted water. Process basil, chilli, and garlic in a food processor until fine. Add pine nuts and parmesan, process. Drizzle olive oil with the motor running.\nToss hot spaghetti with 3 tablespoons of pesto. Store remaining pesto in a jar.', 
'Pasta with Fresh Basil and Chilli Pesto.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Peach, Tomato, Buffalo Mozzarella Salad', 'Peach, tomato, mozzeralla salad, .doc', 
'2 ripe peaches\n2 ripe tomatoes\n4 balls buffalo mozzarella\nzest & 1 tsp juice of 1 lemon\nSea salt & black pepper\n3 tbsp basil oil\nExtra prawns (optional)', 
'Slice tomatoes into rough 1-inch pieces. Tear mozzarella and peaches to matching size pieces. Place all in a bowl.\nSqueeze lemon juice, add zest, season with salt and pepper, and drizzle with basil oil. Mix gently by hand. Arrange on plates, garnish with basil, and serve immediately.', 
'Peach, tomato, mozzeralla salad, .doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Playdough', 'Playdough.doc', 
'Uncooked:\n2 cups flour, 1 cup salt, water, 1 tbsp oil, food colouring, oil of cloves.\n\nCooked:\n1 cup flour, ¼ cup salt, 1 cup water, 1 tbsp oil, 2 tsp cream of tartar, food colouring.', 
'Uncooked: Mix flour, salt, colored water into dough. Knead in oil and cloves. Store in fridge.\nCooked: Stir all cooked version ingredients together and cook over low heat for 3-5 minutes until formed. Store in airtight container.', 
'Playdough.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Pork- Hot Spicy Pork', 'Pork- Hot Spicy Pork.doc', 
'Serves 6\n1kg pork fillet, sliced into thin strips\n2 tbsp cornflour\n½ tsp five spice powder\n2 tbsp polyunsaturated oil\n1 tsp fresh ginger, grated\n2 tbsp honey\n2 tsp cornflour mixed with 4 tbsp water\n2 tsp hot chilli sauce\n2 tsp oyster sauce\n4 tbsp lemon juice', 
'Toss pork strips in cornflour and five spice. Heat oil in wok and stir-fry pork over high heat for 3-4 minutes.\nAdd ginger and honey, cook 1 minute. Pour in blended cornflour mixture, chilli sauce, oyster sauce, and lemon juice. Stir until thick and serve immediately.', 
'Pork- Hot Spicy Pork.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Ratatouille', 'Ratatouille.doc', 
'Serves 6\n4 tablespoons olive oil\n2 large onions, sliced\n1-2 aubergines, sliced\n2 large peppers, sliced\n4 medium tomatoes, peeled and sliced\n2 small zucchinis, sliced\n4 cloves garlic, chopped\n1 tsp salt, 6 shakes pepper\n2 tbsp parsley', 
'Warm oil in a large casserole. Layer onions, aubergines, and peppers. Cook gently for 10 minutes without stirring.\nAdd tomatoes, zucchinis, garlic, salt, and pepper. Cover and simmer for 30 minutes. Stir in parsley before serving.', 
'Ratatouille.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Rice with eggplant and Potato Casserole', 'Rice with eggplant and Potato Casserole.doc', 
'1 cup rice, 2 cups water\n1½ tsp salt, ½ tsp pepper, ½ tsp sugar\n1 tsp turmeric, 2 tsp flour, 1 tbsp意 coriander, 1 tbsp lemon juice\n4 tbsp butter\n1 eggplant, cubed\n350g potatoes\n1 tsp cumin', 
'Cook rice in water. Combine spices, flour, lemon juice, and sugar into a paste. Melt butter and cook eggplant and potatoes for 20 minutes.\nLayer half the rice in a casserole dish, add vegetables mixed with spice paste, top with remaining rice and melted butter. Bake for 25 minutes.', 
'Rice with eggplant and Potato Casserole.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Rich Beef Casserole', 'Rich Beef Casserole.doc', 
'Serves 4 to 6\n1 kg round steak\n90g butter (total)\n8 small onions\n250g carrots\n125g bacon pieces\n3 tablespoons of flour\n2 cups water\n1/2 cup dry red wine\n425g can whole tomatoes\n2 beef stock cubes\nsalt, pepper, basil, oregano', 
'1. Cut meat into 2.5cm cubes. Saute carrots, whole onions, and bacon pieces in butter until browned; remove.\n2. Add flour to pan until golden brown, then remove from heat.\n3. Add water, wine, tomatoes, stock cubes, and herbs off heat; stir.\n4. Return pan to heat to boil and thicken. Return meat and vegetables, cover, and simmer for 1.5 hours.', 
'Rich Beef Casserole.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Risotto-Roast Pumpkin and Garlic Risotto', 'Rich Beef Casserole.doc', 
'1 butternut pumpkin\n¼ cup olive oil\n4 cloves garlic\n\nRisotto:\n1.25L vegetable stock\n½ cup white wine\n¼ cup olive oil\n1 onion\n2 cloves garlic\n1 ½ cups arborio rice\n½ cup parmesan\n1 tbsp butter\n¼ cup fresh basil\nPomegranate seeds (optional)', 
'Preheat oven to 180°C. Clean pumpkin, wedge, brush with oil/garlic, and roast for 25-30 minutes.\nRisotto: Simmer stock and wine. In another pan, cook onion and garlic in oil for 2 mins. Add rice, cook 1 min. Add stock 1 cup at a time, stirring until absorbed, until al dente. Stir in parmesan, butter, basil, and seasonings. Top with pumpkin.', 
'Risotto-Roast Pumpkin and Garlic Risotto .doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Rosie’s Bread', 'Rosies bread.doc', 
'Makes 2 loaves\n9 cups flour\n2 tablespoons Fermipan Yeast\n2 tablespoon Lucimax yeast\n4 teaspoon salt\n2 tablespoon oil\n1½ pints tepid water\n½ cup extra water', 
'Grease bread tins. Mix all ingredients together and knead for 15 minutes.\nPlace in oven at 100°F for 30 minutes to double in size.\nMove higher in oven and bake at 350°F for ½ to ¾ hour.', 
'Rosies bread.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('SOUP- Pea & Ham soup', 'SOUP- Pea & Ham soup.doc', 
'Serves 10\n500g yellow split peas\n2 large onions\n2 large carrots\n¼ bunch celery\n1 smoked ham hock\n4 litres water\nSalt to taste', 
'Rinse and drain peas. Place in a large pot. Grate onions and carrots, chop celery, and add to pot with ham hock and water (no salt yet).\nCover and simmer for 2 hours, stirring occasionally. Remove hock, chop meat, and return meat to pot. Season with salt to taste.', 
'SOUP- Pea & Ham soup.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Salad- Pebre from Chile', 'Salad- Pebre from Chile.doc', 
'1 medium onion or 4 green onions\n½ cup coriander\n2 medium tomatoes\nSalt and pepper\n1 tablespoon oil\n3 tablespoons lemon juice or white vinegar\n1 tablespoon hot chilli sauce', 
'Chop onion, coriander, and tomatoes finely. Mix thoroughly with the oil, lemon juice/vinegar, and chilli sauce. Serve.', 
'Salad- Pebre from Chile.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Savory Pancake Stack', 'Savory Pancake Stack.doc', 
'Serves: 6\nPancakes: 3 eggs, ¾ cup flour, ¼ tsp salt, 1 cup milk, 1 tbsp butter.\nFilling: 2 tbsp butter, 2 tbsp oil, parsley, oregano, 4 onions, 6 zucchinis, salt, pepper.\nSauce: 2 tbsp butter, 2 tbsp flour, 1½ cups milk, 2 eggs, ¼ cup parmesan.', 
'Pancakes: Whisk batter, rest 1 hour, cook ~10 large pancakes.\nFilling: Fry sliced onions in butter/oil. Shred zucchini, fry on high until dry. Combine with onion and herbs.\nSauce: Cook butter/flour, add milk to boil. Temper into beaten eggs, stir in parmesan.\nAssemble: Layer pancakes, filling, and sauce in an ovenproof dish. Top with final sauce/parmesan and bake for 30 minutes.', 
'Savory Pancake Stack.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Sour cream scones', 'Sour cream scones.doc', 
'2 cups SR flour\n1 egg\n1 tablespoon sugar\n½ cup sour cream\n⅓ cup milk', 
'Beat egg and sugar until fluffy. Add sour cream and milk; mix thoroughly. Add sifted flour to form a soft dough.\nKnead lightly on floured surface, pat to 2cm thickness, and cut into rounds. Glaze with milk and bake in a very hot oven for 10 to 15 minutes.', 
'Sour cream scones.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Spanakopita', 'Spanakopita.doc', 
'Serves 8\n1kg spinach\n1 onion, chopped\n1 cup spring onions\n½ cup parsley\n2 tsp dill or fennel\n¼ tsp nutmeg\n½ cup cottage cheese\n1 cup feta cheese\n¼ cup parmesan\n4 eggs, beaten\n10 sheets filo pastry\nMelted butter or olive oil', 
'Cook spinach for 7-8 minutes, drain and press dry. Fry onions and spring onions. Combine spinach, onions, herbs, nutmeg, cheeses, and eggs.\nLine a 25x30cm dish with 5 sheets of buttered filo. Add filling, top with remaining 5 sheets of buttered filo. Score top, sprinkle with water, and bake at 180°C for 45 minutes.', 
'Spanakopita.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Tabbouleh', 'Tabbouleh.doc', 
'Serves 8\n250g burghul (cracked wheat)\n1½ cups chopped parsley\n½ cup chopped mint\n1 dozen shallots\n½ cup lemon juice\n½ cup salad oil\nSalt and pepper\nTomato wedges', 
'Soak burghul for one hour, drain and squeeze completely dry.\nPlace in a bowl with parsley, mint, and shallots. Toss with lemon juice and oil. Season with salt and pepper. Garnish with tomato wedges.', 
'Tabbouleh.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Tart-Vegetarian- Roasted Pumpkin and Spinach Tart', 'Tart-Vegetarian- Roasted Pumpkin and Spinach Tart.doc', 
'1 Japanese pumpkin, cubed\n2 onions, sliced\n2 tablespoons parsley\n2 tablespoons olive oil\n1 bunch spinach, shredded\n1 clove garlic\n200g feta, cubed\n4 eggs\n150ml cream\nPinch nutmeg\nSalt and pepper\nPrepared tart shell', 
'Roast pumpkin in olive oil at 200°C for 30 minutes. Sauté onions, garlic, and spinach for a minute.\nSpoon spinach mixture, pumpkin, and feta into the tart shell keeping them somewhat separate for distinct colors.\nBeat eggs with cream, nutmeg, and seasonings. Pour into tart shell and bake at 180°C for 20 to 30 minutes until set.', 
'Tart-Vegetarian- Roasted Pumpkin and Spinach Tart.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Thelma’s Apple Patty Cakes', 'Thelma- Apple Patty Cakes.doc', 
'2 cups S-R flour\n1 cup chopped apple\n1 egg, beaten\n1 cup milk\n½ cup sugar\n¾ teaspoon baking powder\n2 oz melted butter\n\nTopping:\n2 tbsp brown sugar, ¼ tsp cinnamon and nutmeg', 
'Mix dry ingredients and stir in apple. Combine egg, butter, and milk; mix into flour until just moist (do not over-mix). Spoons into patty tins.\nSprinkle topping ingredients over cakes. Cook in a moderate oven for 15 to 20 minutes.', 
'Thelma- Apple Patty Cakes.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Truffles- Handmade Chocolate Truffles', 'Truffles- Handmade Chocolate Truffles.doc', 
'250 g cooking chocolate\n4 tablespoons liqueur [Baileys or Grand Marnier]\n100ml cream\nCocoa powder for dusting', 
'Bring cream, butter, and liqueur to a boil in a small saucepan. Remove from heat, add chocolate, and stir until smooth. Chill until firm. Roll into balls, dust with cocoa powder, and store in an airtight container.', 
'Truffles- Handmade Chocolate Truffles.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Veal and Eggplant casserole [Sharyn]', 'Veal and Eggplant casserole [Sharyn].doc', 
'6 veal steaks\nFlour, salt, pepper\n120g butter\n¼ cup oil\n½ cup dry white wine\n2 medium eggplants\n250g mozzarella cheese\n¼ cup parmesan\n\nTomato Sauce:\n470g can tomatoes, 1 onion, 1 garlic clove, 30g butter, oregano, basil, 2 tbsp tomato paste, ½ cup water, 2 chicken stock cubes, ½ tsp sugar', 
'Coat veal in seasoned flour. Brown in butter and oil; place in ovenproof dish. Deglaze pan with wine, salt, and pepper; reduce by half, add extra butter, and pour over veal.\nSauce: Sauté onion and garlic in butter. Add tomatoes, tomato paste, water, stock cubes, sugar, and herbs; simmer 20 minutes. Pour over veal.\nSlice, flour, and fry eggplant. Overlap on sauce, cover with mozzarella and parmesan. Bake 30 minutes.', 
'Veal and Eggplant casserole [Sharyn].doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Vegetarian- Eggplant Casserole', 'Vegetarian- Eggpalnt casserole.doc', 
'1 eggplant\n1 onion\n1 carrot\n1 capsicum\n1 tomato\n1 tablespoon parsley\n1 tablespoon butter\n1 cup cooked rice\nSalt, breadcrumbs, grated cheese, paprika', 
'Peel eggplant and steam for 15 minutes. Sauté onion, carrot, parsley, and capsicum in butter. Combine with eggplant and rice; season to taste.\nTransfer mixture into a casserole dish, top with cheese and breadcrumbs, and sprinkle with paprika. Bake for 30 minutes.', 
'Vegetarian- Eggpalnt casserole.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Vegetarian- Savory Bean Pot', 'Vegetarian- Roasted Pumpkin and Spinach Tart.doc', 
'Serves 4\n2 tbsp vegetable oil\n2 vegetable bouillon cubes\n2 onions, chopped\n2 apples, grated\n2 carrots, grated\n3 tbsp tomato paste\n1¼ cups water\n2 tbsp white wine vinegar\nSour cream\n1 tbsp dried mustard\n1 tsp oregano\n1 tsp cumin\n2 tsp brown sugar\n3 cups red kidney beans, cooked', 
'Heat oil and sauté bouillon cubes, onions, apples, and carrots for 5 minutes. Mix tomato paste with water, then add to pan along with vinegar, mustard, oregano, cumin, and sugar. Simmer 2 minutes.\nAdd kidney beans, transfer to a casserole dish, and bake at 350°F for 35-40 minutes (add water halfway if needed). Top with sour cream swirls.', 
'Vegetarian- Roasted Pumpkin and Spinach Tart.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Vegetarian- Sweet Vegies', 'Vegetarian- Sweet Vegies.doc', 
'¼ cup oil\n1 cup chopped onion\n2 cloves garlic\n1 dessertspoon honey\n1 teaspoon pepper\n1 cup chopped tomatoes\n1½ cups chopped pumpkin\n½ cup celery\n½ cup currants\nLemon juice\nPinch of nutmeg', 
'Heat oil and fry onions and garlic. Add honey, pepper, and nutmeg. Add pumpkin and celery, cooking until the pumpkin is soft. Stir in currants and lemon juice to taste.', 
'Vegetarian- Sweet Vegies.doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Vegetarian- Curried Chick Peas [Sharyn]', 'Vegetarian-Curried Chick Peas [Sharyn].doc', 
'2 cups chick peas (soaked overnight)\n3 tablespoons butter\n1 teaspoon cumin seeds\n1 medium onion, chopped\n1 inch ginger, chopped\n1 teaspoon turmeric\n½ teaspoon ground cumin\n1 teaspoon coriander\n1 teaspoon garam masala\n¼ teaspoon chilli powder\nSalt', 
'Boil chick peas in 6 cups of salted water; simmer 1 hour. Melt butter, fry cumin seeds for 1 minute, then add onion and ginger.\nMix turmeric, ground cumin, coriander, garam masala, and chilli powder with 2 tbsp water to form a paste. Fry paste with onions for 3 minutes.\nAdd chick peas and their cooking liquid, bring to a boil, then cover and simmer for 30 minutes.', 
'Vegetarian-Curried Chick Peas [Sharyn].doc');

INSERT INTO recipes (title, category, ingredients, instructions, source_file) VALUES 
('Vegetarian- Vegetable Curry [Sharyn]', 'Vegetarian-Vegetable Curry [Sharyn].doc', 
'4-6 Servings\n3 tablespoon oil\n2 medium onions\n1 ½ inch ginger\n2 garlic cloves\n2 green chillies, chopped\n1 teaspoon turmeric\n1 tablespoon coriander\n⅔ cup beans\n⅔ cup peas\n1 tablespoon paprika\n½ teaspoon cayenne\n¼ teaspoon fenugreek\n¼ teaspoon black pepper\n2 tablespoons lemon juice\n½ kg potatoes, cubed\n1 turnip, cubed\n3 carrots, sliced\n425g canned tomatoes', 
'Heat oil and add onions, ginger, garlic, paprika, cayenne, fenugreek, and pepper. Mix lemon juice and a little water to make a smooth paste; add to onions and fry for 5 minutes.\nAdd potatoes, turnip, and carrots; fry for 5 minutes stirring constantly. Stir in tomatoes, beans, peas, and turmeric. Bring to boil, reduce heat, cover, and simmer 25 minutes.', 
'Vegetarian-Vegetable Curry [Sharyn].doc');

COMMIT;